
let group='Browsing',values=Object.fromEntries(settingsSchema.map(x=>[x.key,x.value])),saved={...values},revision=1,pending=null;const acknowledged=new Set();
function draw(){document.getElementById('category-title').textContent=group;const box=document.getElementById('settings');box.replaceChildren();settingsSchema.filter(x=>window.r4SettingsQuery?(x.label+' '+x.group+' '+x.key).toLowerCase().includes(window.r4SettingsQuery.toLowerCase()):x.group===group).forEach(s=>{const label=document.createElement('label');label.className='settings-row';const text=document.createElement('span');text.textContent=s.label+(s.key==='zoom'?' (%)':'');label.append(text);if(s.key==='hdrMode'){const link=document.createElement('a');link.href='../hdr/index.html';link.dataset.key='hdrMode';link.dataset.nativePreference='';link.textContent='Open HDR preference';link.setAttribute('aria-label','Open HDR preference');label.append(link);box.append(label);return;}const input=document.createElement(s.kind==='select'?'select':'input');input.dataset.key=s.key;input.setAttribute('aria-label',s.label);if(s.options)s.options.forEach(v=>input.add(new Option(s.key==='text'?Math.round(v*100)+'%':String(v),String(v))));else input.type=s.kind==='boolean'?'checkbox':s.kind==='number'?'number':s.kind==='url'?'url':'text';if(s.kind==='boolean')input.checked=values[s.key];else input.value=s.key==='zoom'?Math.round(values[s.key]*100):values[s.key];if(s.min!==undefined){const scale=s.key==='zoom'?100:1;input.min=s.min*scale;input.max=s.max*scale;input.step=s.step*scale}input.disabled=!!s.readOnly;input.onchange=()=>{const v=s.kind==='boolean'?input.checked:typeof s.value==='number'?Number(input.value)/(s.key==='zoom'?100:1):input.value;if(s.danger&&((s.key==='consoleBlock'&&!v)||(s.key==='jit'&&v))){pending={key:s.key,value:v};document.getElementById('danger-copy').textContent=s.key==='consoleBlock'?'Disabling the console block can let websites reach console administration services. Keep it enabled unless you understand this risk.':'JIT changes execution behavior and requires a new web process. The engine must verify support before enabling it.';obUI.openDialog('danger')}else{values[s.key]=v;dirty()}};label.append(input);box.append(label)});if(group==='Experimental'){const p=document.createElement('p');p.className='help';p.textContent='GPU controls stay unavailable until the engine advertises a reviewed capability.';box.append(p)}dirty()}
function dirty(){document.getElementById('dirty').textContent=JSON.stringify(saved)===JSON.stringify(values)?'No pending changes':'Changes not saved'}
function restoreSettingsInvoker(invoker){
 const active=document.activeElement;
 if(active&&active!==document.body&&active.isConnected&&!active.disabled&&active.getClientRects().length)return;
 const key=invoker?.dataset?.key;
 const target=key?[...document.querySelectorAll('[data-key]')].find(e=>e.dataset.key===key):invoker?.id?document.getElementById(invoker.id):null;
 const fallback=document.getElementById('save');
 obUI.focus(target&&!target.disabled&&target.getClientRects().length?target:!fallback.disabled?fallback:document.querySelector('[data-category]'));
}
const dangerDialog=document.getElementById('danger');
document.getElementById('danger-accept').onclick=()=>{if(!pending||!dangerDialog.open)return;values[pending.key]=pending.value;acknowledged.add(pending.key);dangerDialog.close()};
document.getElementById('danger-cancel').onclick=()=>{if(dangerDialog.open)dangerDialog.close()};
dangerDialog.addEventListener('close',()=>{
 if(dangerDialog.open||!pending)return;
 const invoker=[...document.querySelectorAll('[data-key]')].find(e=>e.dataset.key===pending.key);
 pending=null;draw();restoreSettingsInvoker(invoker);
});
for(const name of [...new Set(settingsSchema.map(x=>x.group))]){const b=document.createElement('button');b.textContent=name;b.dataset.category=name;b.onclick=()=>{group=name;window.r4SettingsQuery='';const search=document.getElementById('settings-search');if(search)search.value='';draw();obUI.focus(b)};document.getElementById('categories').append(b)}
document.getElementById('save').onclick=async()=>{if(values.home&&!r2.url(values.home)){r2.toast('Use an http or https home address.');return}if(Number(values.keeploaded)>Number(values.tablimit)){r2.toast('Loaded tabs cannot exceed the tab limit.');return}for(const s of settingsSchema){if(s.kind==='number'&&(!Number.isFinite(values[s.key])||values[s.key]<s.min||values[s.key]>s.max)){r2.toast('Check the value for '+s.label);return}}const changes=Object.fromEntries(Object.entries(values).filter(([k,v])=>k!=='hdrMode'&&v!==saved[k]));const saveInvoker=document.activeElement;try{const result=await r2.request('settings.write',{revision,changes,confirmed:[...acknowledged]},()=>({revision:revision+1,values:{...values},restartRequired:changes.jit!==undefined||changes.resolution!==undefined}));saved={...result.values};values={...saved};revision=result.revision;acknowledged.clear();draw();r2.toast((window.omnibloomHost?'Saved':'Saved in preview')+(result.restartRequired?' · restart required':''))}catch(e){r2.toast(e.message)}finally{restoreSettingsInvoker(saveInvoker)}};document.getElementById('discard').onclick=()=>{values={...saved};acknowledged.clear();draw();r2.toast('Pending changes discarded.')};draw();